from pathlib import Path
import json

root = Path("assets/datasets/scifact")
lab = json.loads((root / "retrieval_lab.json").read_text())

train = {s["id"] for s in lab["samples"] if s["role"] == "train"}
test = {s["id"] for s in lab["samples"] if s["role"] == "test"}
assert train.isdisjoint(test)
# A reranker cannot recover documents absent from its input candidate set.
candidate_ids = {d for d, _ in lab["samples"][0]["rankings"]["tfidf"]}
ceiling = len(candidate_ids & set(lab["samples"][0]["relevant"])) / len(
    lab["samples"][0]["relevant"]
)
print(ceiling)

দুটি শাখায় Rank $2$ পাওয়া একটি Document কীভাবে যেকোনো এক শাখার Rank $1$ Document-কে ছাড়িয়ে শীর্ষে চলে আসে, তা নিচের ছোট হিসাব ও কোডে সরাসরি দেখুন!

> **উদাহরণ:** ধরা যাক RRF ধ্রুবক $c = 60$ এবং দুটি শাখার ফলাফল হলো `[A, C]` ও `[B, C]`:
> - **A** (শুধু প্রথম শাখায় Rank $1$): $\frac{1}{60 + 1} = \frac{1}{61} \approx 0.016393$
> - **B** (শুধু দ্বিতীয় শাখায় Rank $1$): $\frac{1}{60 + 1} = \frac{1}{61} \approx 0.016393$
> - **C** (উভয় শাখায় Rank $2$): $\frac{1}{60 + 2} + \frac{1}{60 + 2} = \frac{2}{62} = \frac{1}{31} \approx 0.032258$

```python
def rrf_fuse(branches: list[list[str]], c: int = 60) -> list[tuple[str, float]]:
    scores: dict[str, float] = {}
    for branch in branches:
        assert len(branch) == len(set(branch)), "Duplicate ID in branch!"
        for rank, doc_id in enumerate(branch, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (c + rank)
    return sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))

print(rrf_fuse([["A", "C"], ["B", "C"]], c=60))
```

- **লক্ষণীয় দিক:** মূল শাখায় `A`-র Raw Score কত বিশাল ছিল তা RRF সূত্রে আসেই না; ঠিক একইভাবে পরস্পর-সম্পর্কিত (`Correlated`) দুটি শাখা একমত হলে দ্বিগুণ অবদান জমা হয়ে `C` সহজেই জিতে যায়।
